import sys
from math import sqrt

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def generate_primes(limit):
    primes = []
    for num in range(2, limit + 1):
        if is_prime(num):
            primes.append(num)
    return primes

def find_primes_sum(target, primes, squares, cubes):
    for p1 in primes:
        for p2 in squares:
            for p3 in cubes:
                if p1 + p2 + p3 == target:
                    return p1, int(sqrt(p2)), int(sqrt(sqrt(p3)))
    return 0, 0, 0

def main():
    limit = 10**6
    primes = generate_primes(int(limit ** (1/3)) + 1)
    squares = [p * p for p in primes if p * p < limit]
    cubes = [p * p * p for p in primes if p * p * p < limit]

    for line in sys.stdin:
        n = int(line.strip())
        if n == 0:
            break
        result = find_primes_sum(n, primes, squares, cubes)
        print(f"{result[0]} {result[1]} {result[2]}")

if __name__ == "__main__":
    main()
